func (o *StatValue) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Match":
		rel, ok := retrieved.(*Match)
		if !ok {
			return fmt.Errorf("statValue cannot load %T as %q", retrieved, name)
		}

		o.R.Match = rel
		o.R.Loaded.Match = true

		if rel != nil {
			rel.R.StatValues = StatValueSlice{o}
		}
		return nil
	case "Player":
		rel, ok := retrieved.(*Player)
		if !ok {
			return fmt.Errorf("statValue cannot load %T as %q", retrieved, name)
		}

		o.R.Player = rel
		o.R.Loaded.Player = true

		if rel != nil {
			rel.R.StatValues = StatValueSlice{o}
		}
		return nil
	case "Round":
		rel, ok := retrieved.(*Round)
		if !ok {
			return fmt.Errorf("statValue cannot load %T as %q", retrieved, name)
		}

		o.R.Round = rel
		o.R.Loaded.Round = true

		if rel != nil {
			rel.R.StatValues = StatValueSlice{o}
		}
		return nil
	case "RoundTeam":
		rel, ok := retrieved.(*RoundTeam)
		if !ok {
			return fmt.Errorf("statValue cannot load %T as %q", retrieved, name)
		}

		o.R.RoundTeam = rel
		o.R.Loaded.RoundTeam = true

		if rel != nil {
			rel.R.StatValues = StatValueSlice{o}
		}
		return nil
	case "Stat":
		rel, ok := retrieved.(*Stat)
		if !ok {
			return fmt.Errorf("statValue cannot load %T as %q", retrieved, name)
		}

		o.R.Stat = rel
		o.R.Loaded.Stat = true

		if rel != nil {
			rel.R.StatValues = StatValueSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("statValue has no relationship %q", name)
	}
}

