type statValueJoins[Q dialect.Joinable] struct {
	typ       string
	Match     modAs[Q, matchColumns]
	Player    modAs[Q, playerColumns]
	Round     modAs[Q, roundColumns]
	RoundTeam modAs[Q, roundTeamColumns]
	Stat      modAs[Q, statColumns]
}

func (j statValueJoins[Q]) aliasedAs(alias string) statValueJoins[Q] {
	return buildStatValueJoins[Q](buildStatValueColumns(alias), j.typ)
}

func buildStatValueJoins[Q dialect.Joinable](cols statValueColumns, typ string) statValueJoins[Q] {
	return statValueJoins[Q]{
		typ: typ,
		Match: modAs[Q, matchColumns]{
			c: Matches.Columns,
			f: func(to matchColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Matches.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.MatchID),
					))
				}

				return mods
			},
		},
		Player: modAs[Q, playerColumns]{
			c: Players.Columns,
			f: func(to playerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Players.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.PlayerID),
					))
				}

				return mods
			},
		},
		Round: modAs[Q, roundColumns]{
			c: Rounds.Columns,
			f: func(to roundColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Rounds.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoundID),
					))
				}

				return mods
			},
		},
		RoundTeam: modAs[Q, roundTeamColumns]{
			c: RoundTeams.Columns,
			f: func(to roundTeamColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RoundTeams.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoundTeamID),
					))
				}

				return mods
			},
		},
		Stat: modAs[Q, statColumns]{
			c: Stats.Columns,
			f: func(to statColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Stats.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.StatID),
					))
				}

				return mods
			},
		},
	}
}
